#include <stdio.h>
#include<stdlib.h>

void colour(int ** g,int c,int m,int *col)
{
    int i;
    col[0]=1;
    int* temp;
    for(i=1;i<c;i++)
    {
        temp=(int*)calloc(i,sizeof(int));
        int j;
        for(j=0;j<i;j++)
        {
            if(g[i][j]==1)
                temp[j]=col[j];
        }
        int counter=1;
        int l,flag=0;
        //while(flag!=j)
        for(counter=1;(flag!=j);counter++)
        {
            flag=0;
            for(l=0;l<j;l++)
            {
                if(counter!=temp[l])
                    flag++;
            }
        }
        col[i]=counter;
    }
}
